import { Component, AfterViewInit } from '@angular/core';
import { RouterLink } from '@angular/router';
import { initFakeSubmit } from '../../shared/auth-common';

declare const document: any;

@Component({
  selector: 'app-forgot-password',
  standalone: true,
  imports: [RouterLink],
  templateUrl: './forgot-password.component.html',
  styleUrl: './forgot-password.component.css'
})
export class ForgotPasswordComponent implements AfterViewInit {

  ngAfterViewInit(): void {
    const form = document.getElementById('forgot-form');
    const success = document.getElementById('forgot-success');

    initFakeSubmit('forgot-form', 'forgot-submit', () => {
      form.style.display = 'none';
      success.style.display = 'flex';
    });
  }
}
<div class="auth">
  <div class="auth__panel">
    <div class="auth-form">
      <h1 class="auth-form__title">Reset your password</h1>
      <p class="auth-form__subtitle">Enter the email on your account and we'll send you a reset link.</p>

      <form id="forgot-form" class="auth-form__form" novalidate>
        <div class="field__group">
          <label class="field__label" for="forgot-email">Email</label>
          <input id="forgot-email" class="field__input" type="email" required autocomplete="email" />
        </div>

        <button id="forgot-submit" type="submit" class="auth-form__submit">
          <span class="auth-form__submit-label">Send reset link</span>
        </button>
      </form>

      <div id="forgot-success" class="auth-form__success" style="display:none">
        <p>Check your inbox — if that email is registered, a reset link is on its way.</p>
      </div>

      <p class="auth-form__footer">
        Remembered it? <a routerLink="/login">Back to login</a>
      </p>
    </div>
  </div>
</div>
